import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int mod = scanner.nextInt();
        solve(n, mod);
        scanner.close();
    }

    public static void solve(int n, int mod) {
        if (n <= 3) {
            System.out.println(0);
            return;
        }
        long previous_result = 17;
        long current_result = 17;
        int max_size = (n - 1) * (n - 2) / 2 + 1;
        int switchFlag = 1;
        long[][] dp_table = new long[2][max_size + 1];
        // Initialize base case
        dp_table[0][0] = 1;
        dp_table[0][1] = 2;
        dp_table[0][2] = 2;
        dp_table[0][3] = 1;

        for (int m = 4; m < n; m++) {
            int pair_total = m * (m - 1) / 2;
            current_result = (long)(m + 1) * previous_result;
            long cum_sum = 0;

            // Compute prefix sums for dp_table[switch ^ 1]
            for (int i = 0; i < m; i++) {
                cum_sum += dp_table[switchFlag ^ 1][i];
                dp_table[switchFlag][i] = cum_sum % mod;
            }

            // Compute remaining values
            for (int i = m; i <= pair_total / 2; i++) {
                cum_sum += dp_table[switchFlag ^ 1][i];
                cum_sum -= dp_table[switchFlag ^ 1][i - m];
                cum_sum = ((cum_sum % mod) + mod) % mod; // ensure non-negative
                dp_table[switchFlag][i] = cum_sum;
            }

            // Mirror the values for symmetry
            for (int i = 0; i <= pair_total / 2; i++) {
                dp_table[switchFlag][pair_total - i] = dp_table[switchFlag][i];
            }

            long total_accum = 0;
            for (int i = 0; i < pair_total; i++) {
                long temp_sum = 0;
                int start_idx = Math.max(1, -pair_total + i + m + 2);
                for (int j = start_idx; j <= m; j++) {
                    int index = m + 2 - j + i;
                    if (index >= 0 && index <= pair_total) {
                        temp_sum += j * dp_table[switchFlag][index];
                    }
                }
                total_accum += dp_table[switchFlag][i];
                total_accum %= mod;
                temp_sum %= mod;
                current_result += (temp_sum * total_accum) % mod;
                current_result %= mod;
            }

            previous_result = current_result;
            switchFlag ^= 1;
        }
        System.out.println(current_result % mod);
    }
}
